<body>
<div class="app">
  <aside class="sidebar">
    <div class="brand"><span class="apple"></span>Music <span class="beta">Beta</span></div>
    <div class="search"><span>⌕</span>Search</div>
    <nav class="nav">
      <div class="nav-item active btn"><span class="nav-icon">⌂</span>Home</div>
      <div class="nav-item btn"><span class="nav-icon">⊞</span>New</div>
      <div class="nav-item btn"><span class="nav-icon">◉</span>Radio</div>
    </nav>
    <div class="bottom">
      <div class="btn"><span class="music-round">♫</span>Open in Music ↗</div>
      <div class="btn">Exit Beta ↗</div>
    </div>
  </aside>
  <main class="main">
    <header class="topbar">
      <div class="controls">
        <button class="control btn">×</button><button class="control btn">◀</button><button class="control play-small btn">▶</button><button class="control btn">▶</button><button class="control btn">↝</button>
      </div>
      <div class="track btn" id="trackButton">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/017.jpg" width="47" height="47">
        <div class="track-info"><div class="track-title">Sacrifice</div><div class="track-artist">Mariah the Scientist — HEARTS SOLD SEPARATELY</div><span class="preview">PREVIEW</span></div>
      </div>
      <div class="volume">⌁ <span class="vol-line"></span><span class="list">☷</span><span class="account">●</span></div>
    </header>
    <section class="hero">
      <div class="hero-logo">Music</div>
      <h1>Discover new music<br>every day.</h1>
      <img class="hero-note" src="__PLACEHOLDER_ASSETS_BASE_DIR__/013.webp" width="300" height="300">
      <p>Get playlists and albums inspired by the artists and genres<br>you’re listening to.</p>
      <button class="start btn" id="startButton">Get Started</button>
      <a class="student btn" href="#">See Student Plan ›</a>
    </section>
  </main>
</div>

<div class="player" id="player">
  <button class="close btn" id="closeButton">×</button>
  <div class="player-card">
    <img class="album" src="__PLACEHOLDER_ASSETS_BASE_DIR__/017.jpg" width="300" height="317">
    <div class="song-head">
      <div class="song-name">Sacrifice</div>
      <div class="song-artist">Mariah the Scientist — HEARTS SOLD SEPARATELY</div>
      <button class="heart btn">☆</button><button class="more btn">•••</button>
    </div>
    <div class="progress"></div>
    <div class="times"><span id="elapsed">0:11</span><span>-1:19</span></div>
    <div class="play-controls">
      <button class="pctrl btn">×</button><button class="pctrl btn">◀</button>
      <button class="pctrl center btn" id="pauseButton">Ⅱ</button>
      <button class="pctrl btn">▶</button><button class="pctrl btn">↝</button>
    </div>
    <div class="soundline"></div>
  </div>
</div>

<script>
  const player=document.getElementById('player');
  const open=()=>player.classList.add('open');
  document.getElementById('trackButton').onclick=open;
  document.getElementById('startButton').onclick=open;
  document.getElementById('closeButton').onclick=()=>player.classList.remove('open');
  let playing=true, seconds=11;
  const pause=document.getElementById('pauseButton'), elapsed=document.getElementById('elapsed');
  pause.onclick=()=>{
    playing=!playing;
    pause.textContent=playing?'Ⅱ':'▶';
  };
  setInterval(()=>{
    if(playing && player.classList.contains('open')){
      seconds++;
      let m=Math.floor(seconds/60), s=String(seconds%60).padStart(2,'0');
      elapsed.textContent=m+':'+s;
    }
  },1000);
</script>
